const output = $json['Resposta'] || $json.output || '';
const midiaRegex = /\[MIDIA:\s*([^|\]]+)\|([^|\]]+)(?:\|([^\]]+))?\]/gi;
const midias = [];
let match;
while ((match = midiaRegex.exec(output)) !== null) {
  const part1 = match[1].trim(); // url
  const part2 = match[2].trim(); // tipo ou descricao
  const part3 = match[3] ? match[3].trim() : null; // descricao (se tiver)

  let url, tipo, descricao;
  if (part3) {
    // formato novo: url | tipo | descricao
    url = part1; tipo = part2.toLowerCase(); descricao = part3;
  } else {
    // formato antigo: url | descricao — detecta tipo pela URL
    url = part1; descricao = part2;
    tipo = url.includes('.mp4') || url.includes('.mov') || url.includes('video') ? 'video' : 'foto';
  }
  midias.push({ url, tipo, descricao });
}
const textoLimpo = output.replace(/\[MIDIA:[^\]]+\]/gi, '').trim();
return [{
  json: {
