// Fallback acionado quando Parser Chain falha
// Estratégia de sourcing (prioridade):
//   1) $input.first().json.Resposta  — dado direto no ramo de erro
//   2) $json.Resposta                — contexto imediato
//   3) $('Delete Memory').first().json.Resposta — fallback defensivo secundário

let resposta = '';

try { resposta = $input.first().json.Resposta || ''; } catch(_) {}

if (!resposta) {
  try { resposta = $json.Resposta || ''; } catch(_) {}
}

if (!resposta) {
  try { resposta = $('Delete Memory').first().json.Resposta || ''; } catch(_) {}
}

if (!resposta || resposta.trim() === '') {
  return [{ json: { output: { messages: ['Desculpe, ocorreu um erro ao processar a resposta.'] } } }];
}

// Split por sentenças: quebra em '.', '!', '?' seguidos de espaço ou fim
const sentences = resposta
  .replace(/([.!?])\s+/g, '$1\n')
  .split('\n')
  .map(s => s.trim())
  .filter(s => s.length > 0);

// Agrupa sentenças em blocos de até ~600 chars
const MAX_BLOCK = 600;
const messages = [];
let current = '';
for (const s of sentences) {
  if (current.length + s.length + 1 > MAX_BLOCK && current.length > 0) {
    messages.push(current.trim());
    current = s;
  } else {
    current = current ? current + ' ' + s : s;
  }
}
if (current.trim()) messages.push(current.trim());

// Corte defensivo: se algum bloco ainda for maior que MAX_BLOCK, fatia no último espaço
const final = [];
for (const msg of (messages.length > 0 ? messages : [resposta])) {
  if (msg.length > MAX_BLOCK) {
    let remaining = msg;
    while (remaining.length > MAX_BLOCK) {
      let cut = remaining.lastIndexOf(' ', MAX_BLOCK);
      if (cut <= 0) cut = MAX_BLOCK;
      final.push(remaining.slice(0, cut).trim());
      remaining = remaining.slice(cut).trim();
    }
    if (remaining) final.push(remaining);
  } else {
    final.push(msg);
  }
}

return [{ json: { output: { messages: final.length > 0 ? final : [resposta] } } }];

